-- Demo seed so `supabase db reset` (local) and the preview sandbox yield a
-- pokeable, realistic catalog. Content mirrors the 5 live trails (public
-- marketing copy, no PII). hero_image/gallery hold relative trip_photos paths;
-- the app resolves them to the environment's public bucket URL at render time.
-- Tests do NOT depend on this — each test creates its own isolated fixtures.

insert into public.trails (
  slug, name, short_name, region, region_label, difficulty, difficulty_label,
  price, height, duration, hero_image, excerpt, description, gear, audience,
  included, sort_order, gallery
)
select
  x.slug, x.name, x.short_name, x.region, x.region_label, x.difficulty, x.difficulty_label,
  x.price, x.height, x.duration, x.hero_image, x.excerpt, x.description, x.gear, x.audience,
  x.included, x.sort_order,
  coalesce((select array_agg(g) from jsonb_array_elements_text(x.gallery) g), '{}')
from jsonb_to_recordset($json$
[{"gear":"נעלי הליכה או סנדלי מים, בגד ים, מגבת, 2 ליטר מים, כובע, קרם הגנה ואוכל ליום.","name":"טיול סנפלינג רטוב בנחל ג'ילבון","slug":"nahal-gilbon","price":180,"height":"מפל ג'ילבון 40מ' · מפל דבורה 17מ'","region":"north","excerpt":"במרכז הגולן, ליד קצרין. הליכה רגלית לאורך המים בין צמחייה ירוקה וגלישה בשני מפלים ישירות לבריכות מים קרירים.","gallery":["nahal-gilabon/20220505_145210-scaled.jpg","nahal-gilabon/20220505_145804-scaled.jpg","nahal-gilabon/20220505_170016-scaled.jpg","nahal-gilabon/20220608_164924-scaled.jpg","nahal-gilabon/20220608_1649370-scaled.jpg","nahal-gilabon/20220608_164946-scaled.jpg","nahal-gilabon/20220608_165546-scaled.jpg"],"audience":"מתאים למשפחות, למתחילים ולמנוסים כאחד. ניתן לעקוף את הגלישות ולרדת ברגל.","duration":"יום טיול מלא","included":"הדרכה מקצועית, ציוד סנפלינג תקני (רתמה, קסדה, חבלים) וביטוח ספורט אתגרי.","difficulty":"easy-medium","hero_image":"nahal-gilabon/20220505_145108-scaled.jpg","short_name":"נחל ג'ילבון","sort_order":1,"description":"במרכז הגולן, ליד קצרין. הליכה רגלית לאורך המים בין צמחייה ירוקה + גלישה בשני מפלים: מפל דבורה (17 מ') ומפל ג'ילבון (40 מ'), ישירות לבריכות מים קרירים וממשיכים בשחייה. ניתן לעקוף את הגלישה ולרדת ברגל.","region_label":"צפון · רמת הגולן","difficulty_label":"קל-בינוני"},{"gear":"נעלי הליכה סגורות, 3 ליטר מים, כובע, קרם הגנה, חטיף אנרגיה ואוכל ליום.","name":"סנפלינג בנחל קומראן","slug":"nahal-qumran","price":200,"height":"6 מפלים במצוק ההעתקים","region":"south","excerpt":"בצפון מדבר יהודה ליד קיבוץ קליה. 6 מפלים בסלעי מצוק ההעתקים, נוף לים המלח והרי מואב.","gallery":["nahal-qumran/IMG_20201124_112149-scaled.jpg","nahal-qumran/IMG_6763-scaled.jpg","nahal-qumran/IMG_6769-scaled.jpg","nahal-qumran/IMG_6773-scaled.jpg","nahal-qumran/IMG_6780-scaled.jpg","nahal-qumran/IMG_6782-scaled.jpg","nahal-qumran/IMG_6788-scaled.jpg","nahal-qumran/IMG_6792-scaled.jpg","nahal-qumran/IMG_6800-scaled.jpg","nahal-qumran/IMG_6805-scaled.jpg"],"audience":"מתאים למתחילים ולמנוסים. נגישות נוחה לאזור ים המלח.","duration":"יום טיול מלא","included":"הדרכה מקצועית, ציוד סנפלינג תקני וביטוח ספורט אתגרי.","difficulty":"easy-medium","hero_image":"nahal-qumran/IMG_20201124_094923-scaled.jpg","short_name":"נחל קומראן","sort_order":2,"description":"בצפון מדבר יהודה ליד קיבוץ קליה. 6 מפלים בסלעי מצוק ההעתקים, נוף לים המלח והרי מואב. מתאים למתחילים ולמנוסים. סמוך לגן לאומי עתיקות קומראן.","region_label":"דרום · מדבר יהודה","difficulty_label":"קל-בינוני"},{"gear":"נעלי מים / סנדלים יציבים, בגד ים, מגבת, שק שינה לחיתול, 2 ליטר מים, אוכל ליום.","name":"טיול סנפלינג רטוב בנקיק השחור – זויתן תיכון","slug":"nakik-shachor","price":220,"height":"מפלי מים זורמים · קניונינג מאושר","region":"north","excerpt":"מסלול הסנפלינג היחיד בארץ בו גולשים במפלי מים זורמים. קניון בזלט שחור עם בריכות פסטורליות ושחייה.","gallery":["black-crevice-zavitan/10.jpg","black-crevice-zavitan/2.jpg","black-crevice-zavitan/3.jpg","black-crevice-zavitan/4.jpg","black-crevice-zavitan/5.jpg","black-crevice-zavitan/6.jpg","black-crevice-zavitan/7.jpg","black-crevice-zavitan/8.jpg","black-crevice-zavitan/9.jpg","black-crevice-zavitan/cover-1.jpg"],"audience":"לבעלי ניסיון בסיסי בסנפלינג. מתאים לחובבי הרפתקה שאוהבים מים.","duration":"יום טיול מלא","included":"הדרכה מקצועית, ציוד סנפלינג וקניונינג תקני, חליפות ניאופרן (בעונה) וביטוח.","difficulty":"medium","hero_image":"black-crevice-zavitan/1.jpg","short_name":"נקיק שחור / זויתן תיכון","sort_order":3,"description":"הנקיק השחור הוא אחד ממסלולי הטיול היפים שיש בצפון הארץ והוא מסלול הסנפלינג היחידי בו גולשים במפלי מים זורמים, קניונינג אשר מאושר בגלישה. הליכה לאורך הנחל בין בריכות פסטורליות עם אפשרות שחייה, וגלישה לחלקן.","region_label":"צפון · רמת הגולן","difficulty_label":"בינוני"},{"gear":"נעלי הליכה סגורות ואיתנות, 4 ליטר מים, כובע, קרם הגנה, כפפות עבודה ואוכל ליום.","name":"סנפלינג בנחל רחף","slug":"nahal-rachaf","price":240,"height":"סדרת 9 מפלים אל ים המלח","region":"south","excerpt":"בדרום מדבר יהודה, ליד מצדה. קניון צר ועמוק, יורד לכיוון ים המלח בסדרת 9 מפלים.","gallery":["nahal-rahaf/3-scaled.jpg","nahal-rahaf/35751881-6e77-425c-8551-75ab4cc333f7.jpg","nahal-rahaf/45fcb7c0-f9aa-49af-83ba-f25078efb556.jpg","nahal-rahaf/edaea2d0-05ee-4eed-be33-dd2e743da4a2.jpg","nahal-rahaf/IMG_20200530_080351-scaled.jpg","nahal-rahaf/IMG_20200530_081216-1-scaled.jpg","nahal-rahaf/IMG_20200530_083834-scaled.jpg","nahal-rahaf/IMG_20200530_084605-scaled.jpg","nahal-rahaf/IMG_20200530_090741-scaled.jpg","nahal-rahaf/IMG_20200530_091428-1-scaled.jpg","nahal-rahaf/IMG_20200530_091428-scaled.jpg","nahal-rahaf/IMG_20200530_093156-scaled.jpg","nahal-rahaf/IMG_20200530_093200-scaled.jpg","nahal-rahaf/IMG_20200530_120012-scaled.jpg"],"audience":"מיועד למיטיבי לכת ולמי שכבר התנסה בסנפלינג בעבר.","duration":"יום טיול מלא","included":"הדרכה מקצועית, ציוד סנפלינג תקני וביטוח ספורט אתגרי.","difficulty":"medium-hard","hero_image":"nahal-rahaf/0c97a168-5d77-449a-837d-d13701fe1efe.jpg","short_name":"נחל רחף","sort_order":4,"description":"בדרום מדבר יהודה, ליד מצדה. קניון צר ועמוק, יורד לכיוון ים המלח בסדרת 9 מפלים. לאחר שיטפונות נוצרות בריכות מים טריות למשך חודשים; חלק מהגלישות ישירות לבריכות.","region_label":"דרום · מדבר יהודה","difficulty_label":"בינוני-קשה"},{"gear":"נעלי הליכה נוחות, 1.5 ליטר מים, כובע ואוכל קל. ניתן להביא שמיכה לפיקניק.","name":"סנפלינג במצוק דלתון","slug":"mitzpe-dalton","price":180,"height":"כ-20 מטר","region":"north","excerpt":"ביער ביריה בגליל העליון. מצוק קטן, שקט ואינטימי עם נוף לגולן, עמק החולה והחרמון.","gallery":["dalton-cliff/10496138_799096216809673_3015183436283769707_o.jpg","dalton-cliff/1908394_799096350142993_1631490161793318339_n.jpg","dalton-cliff/20190403_170410-scaled.jpg","dalton-cliff/20201211_100017-scaled.jpg","dalton-cliff/20201211_102608-scaled.jpg","dalton-cliff/20201211_132621-scaled.jpg","dalton-cliff/7d7bd2b6-1a97-4ca5-b0e8-20389deedf37.jpg","dalton-cliff/cdbfa2b1-f5d8-4668-8663-58f8ae851157.jpg","dalton-cliff/d1-scaled.jpg","dalton-cliff/d2-scaled.jpg","dalton-cliff/d3-scaled.jpg","dalton-cliff/d4-scaled.jpg","dalton-cliff/dalton-cliff-01.jpg","dalton-cliff/dalton-cliff-10.jpg"],"audience":"מתאים להתנסות ראשונה, למשפחות עם ילדים קטנים ולחוששים מגבהים.","duration":"חצי יום","included":"הדרכה מקצועית וסבלנית, ציוד סנפלינג תקני וביטוח ספורט אתגרי.","difficulty":"easy","hero_image":"dalton-cliff/09b05f12-f7aa-48d7-82b0-97086baabe12.jpg","short_name":"מצוק דלתון","sort_order":5,"description":"מצוק דלתון נמצא ביער ביריה בגליל העליון, לא רחוק מצפת. מצוק קטן, שקט ואינטימי, עם נוף לגולן, עמק החולה והחרמון, ואפשרות פיקניק. גובה כ-20 מטר — מתאים להתנסות ראשונה ולמשפחות עם ילדים קטנים.","region_label":"צפון · הגליל העליון","difficulty_label":"קל"}]
$json$::jsonb) as x(
  slug text, name text, short_name text, region text, region_label text, difficulty text,
  difficulty_label text, price numeric, height text, duration text, hero_image text,
  excerpt text, description text, gear text, audience text, included text, sort_order integer,
  gallery jsonb
)
on conflict (slug) do nothing;

-- One open departure per trail, three weeks out, small capacity for easy manual testing.
insert into public.departures (trail_id, date, departure_time, price, max_capacity, status)
select id, current_date + 21, '08:00', price, 12, 'open' from public.trails;
